<?php
require_once '_bootstrap.php';require_admin_permission('dashboard.view');$db=admin_db();$metrics=[];
foreach(['customers'=>'SELECT COUNT(*) n FROM users','packages'=>"SELECT COUNT(*) n FROM packages WHERE status='published'",'bookings'=>'SELECT COUNT(*) n FROM bookings','pending'=>"SELECT COUNT(*) n FROM bookings WHERE status='pending'",'revenue'=>"SELECT COALESCE(SUM(amount),0) n FROM payments WHERE status IN ('paid','refunded')",'refunds'=>"SELECT COALESCE(SUM(-amount),0) n FROM payments WHERE status='refunded'",'messages'=>"SELECT COUNT(*) n FROM message WHERE status='open'"] as $key=>$sql)$metrics[$key]=$db->query($sql)->fetch_assoc()['n'];
$search=trim($_GET['q']??'');$where='';$params=[];if($search!==''){$where='WHERE b.booking_reference LIKE ? OR p.transaction_reference LIKE ? OR b.customer_name LIKE ?';$term='%'.$search.'%';$params=[$term,$term,$term];}$recent=$db->execute_query("SELECT p.id,p.transaction_reference,p.amount,p.method,p.status,p.created_at,b.id booking_id,b.booking_reference,b.customer_name,b.destination,b.payment_status FROM payments p JOIN bookings b ON b.id=p.booking_id $where ORDER BY p.created_at DESC,p.id DESC LIMIT 10",$params);$pageTitle='Dashboard';include '_header.php';?>
<div class="page-head"><div><span>India tourism operations</span><h1>Dashboard</h1></div><a class="primary-btn" href="packages.php?action=new"><i class="fa-solid fa-plus"></i>Add package</a></div><section class="metric-grid"><?php foreach([['fa-users','Customers',$metrics['customers']],['fa-map-location-dot','Indian packages',$metrics['packages']],['fa-calendar-check','Bookings',$metrics['bookings']],['fa-clock','Pending',$metrics['pending']],['fa-wallet','Net revenue',inr($metrics['revenue'])],['fa-rotate-left','Refunded',inr($metrics['refunds'])],['fa-inbox','Open messages',$metrics['messages']]] as $m):?><article class="metric"><i class="fa-solid <?php echo $m[0];?>"></i><span><?php echo $m[1];?></span><strong><?php echo $m[2];?></strong></article><?php endforeach;?></section><section class="panel"><div class="panel-head region-tools"><h2>Recent payments and refunds</h2><?php admin_directory_tools('index.php','Booking or transaction reference');?></div><div class="table-wrap"><table><thead><tr><th>Transaction reference</th><th>Booking / customer</th><th>Type</th><th>Method</th><th>Amount (INR)</th><th>Date</th><th>Details</th></tr></thead><tbody><?php if($recent->num_rows):while($p=$recent->fetch_assoc()):?><tr><td><strong><?php echo e($p['transaction_reference']?:'-');?></strong><small><?php echo e($p['booking_reference']);?></small></td><td><?php echo e($p['customer_name']);?><small><?php echo e($p['destination']);?></small></td><td><span class="pill"><?php echo e($p['status']==='refunded'?'Refund':ucfirst($p['status']));?></span><small><?php echo e(str_replace('_',' ',$p['payment_status']));?></small></td><td><?php echo e(strtoupper(str_replace(['practice_','demo_','admin_'],'',$p['method'])));?></td><td class="<?php echo (float)$p['amount']<0?'amount-negative':'amount-positive';?>"><?php echo inr($p['amount']);?></td><td><?php echo e(date('d M Y',strtotime($p['created_at'])));?><small><?php echo e(date('h:i A',strtotime($p['created_at'])));?></small></td><td><a class="icon-btn" href="booking-details.php?id=<?php echo (int)$p['booking_id'];?>" title="View full details"><i class="fa-solid fa-eye"></i></a></td></tr><?php endwhile;else:?><tr><td colspan="7">No matching transactions found.</td></tr><?php endif;?></tbody></table></div><div class="panel-footer-actions"><a class="reset-btn" href="transactions.php"><i class="fa-solid fa-receipt"></i> Transaction register</a><a class="reset-btn" href="reports.php"><i class="fa-solid fa-chart-column"></i> Financial reports</a></div></section><?php include '_footer.php';?>
